return {["sort"]=0,["roomList"]={{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[翠竹林]],["permission"]=0,["rightDown"]=[[fb629_03]],["enterable"]=1,["dsc"]=[[一条铺满了鹅卵石的小路，道路两旁长满了翠竹。]],["fullName"]=[[翠竹林(fb629_01)]],["visible"]=1,["unit4"]=[[npc09c]],["dirIndex"]=0,["unit3"]=[[npc09b]],["unit2"]=[[npc09a]],["unit1"]=[[npc08a]],["canLeave"]=1,["id"]=[[fb629_01]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[卧房]],["permission"]=0,["fullName"]=[[卧房(fb629_02)]],["enterable"]=1,["dsc"]=[[房间内空空如也，仅在正门前设有一张紫檀神桌，桌上摆了些祭祀占卜之物。神桌两旁设有厢房，供弟子们生活起居。]],["down"]=[[fb629_06]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc09e]],["unit1"]=[[npc09d]],["canLeave"]=1,["id"]=[[fb629_02]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_04]],["connectPoint"]=0,["name"]=[[小院]],["permission"]=0,["fullName"]=[[小院(fb629_03)]],["enterable"]=1,["dsc"]=[[卧室前的空地，种了一些简单的花花草草，简洁朴素又不失美感，乃练习器乐的绝佳去处。]],["down"]=[[fb629_07]],["visible"]=1,["dirIndex"]=0,["leftUp"]=[[fb629_01]],["canLeave"]=1,["id"]=[[fb629_03]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[卧房]],["permission"]=0,["left"]=[[fb629_03]],["enterable"]=1,["dsc"]=[[这里是嵇广陵弟子们的卧房，正厅内摆放着各种金石丝竹，弟子们的厢房分列于正厅两侧。]],["fullName"]=[[卧房(fb629_04)]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc09g]],["unit2"]=[[npc09f]],["unit1"]=[[npc08b]],["canLeave"]=1,["id"]=[[fb629_04]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_06]],["connectPoint"]=0,["name"]=[[观星抱月坞]],["permission"]=0,["enterable"]=1,["dsc"]=[[空道人门下弟子的所居之处，用水磨石以九宫地支之理搭建而成，中宫位上搭有一数十尺高的观星台，台前设有圭表，用以测量二十四节气。]],["down"]=[[fb629_11]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[观星抱月坞(fb629_05)]],["canLeave"]=1,["id"]=[[fb629_05]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[小院]],["permission"]=0,["left"]=[[fb629_05]],["enterable"]=1,["up"]=[[fb629_02]],["dsc"]=[[卧房前的空地，种了一些简单的花花草草，简洁朴素又不失美感，每逢良辰吉日弟子们便在此处卜卦。]],["fullName"]=[[小院(fb629_06)]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc09i]],["unit1"]=[[npc09h]],["canLeave"]=1,["id"]=[[fb629_06]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[竹弦馆]],["permission"]=0,["fullName"]=[[竹弦馆(fb629_07)]],["enterable"]=1,["up"]=[[fb629_03]],["dsc"]=[[竹弦馆以空瓮累墙，瓮口向着室内，如此一来即使屋内百人齐奏，声振屋瓦，在屋外人听来不过是声若蚊蝇。]],["down"]=[[fb629_12]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc08c]],["canLeave"]=1,["id"]=[[fb629_07]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[醉池]],["permission"]=0,["fullName"]=[[醉池(fb629_08)]],["enterable"]=1,["dsc"]=[[原名莲花池，池边建有莲花檐石亭，历代掌门常于此处设私宴宴请宾客，并与众宾客琴歌酒赋，醉同其乐，遂将此池改名为醉池。]],["down"]=[[fb629_14]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc09j]],["canLeave"]=1,["id"]=[[fb629_08]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[翠竹林]],["permission"]=0,["fullName"]=[[翠竹林(fb629_09)]],["enterable"]=1,["dsc"]=[[一条铺满了鹅卵石的小路，道路两旁长满了翠竹。]],["down"]=[[fb629_15]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc09b]],["unit1"]=[[npc09a]],["canLeave"]=1,["id"]=[[fb629_09]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[明月楼二楼]],["permission"]=0,["fullName"]=[[明月楼二楼(fb629_10)]],["enterable"]=1,["dsc"]=[[屏风将二楼隔成一个个雅座，座上视野极佳，向内能将戏台尽收眼底，向外能欣赏江上美景。]],["down"]=[[fb629_17]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc09k]],["unit2"]=[[npc08e]],["unit1"]=[[npc08d]],["canLeave"]=1,["id"]=[[fb629_10]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[六四居]],["permission"]=0,["fullName"]=[[六四居(fb629_11)]],["enterable"]=1,["up"]=[[fb629_05]],["dsc"]=[[古有八卦为经卦，两卦相重为六十四卦，称为别卦。此居之名由此而来，乃是天竞门五脉之一空道人门下弟子所居之地。]],["down"]=[[fb629_18]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc04]],["canLeave"]=1,["id"]=[[fb629_11]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[清影盗乐居]],["permission"]=0,["fullName"]=[[清影盗乐居(fb629_12)]],["enterable"]=1,["up"]=[[fb629_07]],["dsc"]=[[清影盗乐居坐落于百花园后，桃红柳绿，鸟语花香，乃是嵇广陵门下弟子所居之处。弟子们以器乐见长，金石丝竹声不绝于耳，余音袅袅，令人陶醉。]],["down"]=[[fb629_20]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc03]],["canLeave"]=1,["id"]=[[fb629_12]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[斗笔亭]],["permission"]=0,["fullName"]=[[斗笔亭(fb629_13)]],["enterable"]=1,["dsc"]=[[临池而建，形如斗笔的圆茅亭，由于墨白轩内昏暗不便于读书写字，大多数弟子会将书籍带来此处阅读。]],["down"]=[[fb629_21]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc09l]],["unit1"]=[[npc08f]],["canLeave"]=1,["id"]=[[fb629_13]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_15]],["connectPoint"]=0,["name"]=[[清音台]],["permission"]=0,["fullName"]=[[清音台(fb629_14)]],["enterable"]=1,["up"]=[[fb629_08]],["dsc"]=[[此处原名为清音阁，为四角三层阁，后被改为戏楼，遂称其为清音台。此阁平日里只供弟子们练习使用，因此只设有少许桌椅。三层存放有各种戏乐用道具，种类繁多，琳琅满目。]],["down"]=[[fb629_22]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc09m]],["unit1"]=[[npc08g]],["canLeave"]=1,["id"]=[[fb629_14]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[梨白院]],["permission"]=0,["left"]=[[fb629_14]],["fullName"]=[[梨白院(fb629_15)]],["enterable"]=1,["up"]=[[fb629_09]],["dsc"]=[[弟子居所前的院子，院子里种满了梨树，花开之时如同满天飞雪。]],["down"]=[[fb629_23]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc09o]],["unit1"]=[[npc09n]],["canLeave"]=1,["id"]=[[fb629_15]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[南北居]],["permission"]=0,["fullName"]=[[南北居(fb629_16)]],["enterable"]=1,["dsc"]=[[天竞门第三代门主曾与中原的北神剑殊死一战，而后削发赤脚，遁入空门，并高唱“南来北往走西东，看得浮生总是空......金也空、银也空，死后何曾在手中”。为此天竞门三年内群龙无首，内斗不止。新任门主上任后，新建南北居，用以警惕后世弟子。]],["down"]=[[fb629_25]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc09q]],["unit1"]=[[npc09p]],["canLeave"]=1,["id"]=[[fb629_16]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[戏台]],["permission"]=0,["fullName"]=[[戏台(fb629_17)]],["enterable"]=1,["up"]=[[fb629_10]],["dsc"]=[[檀木搭成的三尺高方形戏台，台上铺着厚厚的红绸地毯，戏台后方设有透雕二龙戏珠戏台屏风。]],["down"]=[[fb629_27]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc08h]],["canLeave"]=1,["id"]=[[fb629_17]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[回廊]],["permission"]=0,["enterable"]=1,["up"]=[[fb629_11]],["dsc"]=[[连接着六四居和三洗关的双面空廊，廊顶用两排原木柱支撑，四面无墙无窗、通透明亮。]],["down"]=[[fb629_29]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[回廊(fb629_18)]],["canLeave"]=1,["id"]=[[fb629_18]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_20]],["connectPoint"]=0,["name"]=[[庆芳园]],["permission"]=0,["fullName"]=[[庆芳园(fb629_19)]],["enterable"]=1,["dsc"]=[[古戏楼后方的小花园，园内湖石假山围绕，中有一石桥直通湖中小亭，亭内置桌椅、茶水供唱戏演出者休息。]],["down"]=[[fb629_30]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc09s]],["unit2"]=[[npc09r]],["unit1"]=[[npc08i]],["canLeave"]=1,["id"]=[[fb629_19]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[百花园]],["permission"]=0,["left"]=[[fb629_19]],["enterable"]=1,["up"]=[[fb629_12]],["dsc"]=[[种植了各式各样的花草树木，鲜花盛开散发幽香，枝叶形成浓密树荫，一年四季景色各不相同。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[百花园(fb629_20)]],["canLeave"]=1,["id"]=[[fb629_20]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[墨白轩]],["permission"]=0,["fullName"]=[[墨白轩(fb629_21)]],["enterable"]=1,["up"]=[[fb629_13]],["dsc"]=[[位于万愁同销阁和斗笔亭间的小屋，乃是门中藏书之地。屋内一个个直通房顶的巨大书架靠墙而立，架上摆满了成百上千卷书册和卷轴，身处其中能够闻到纸张混合驱虫草药的淡香味。屋内虽设有窗口通风，却无阳光直射，又因此处禁止明火，故而稍显昏暗。]],["down"]=[[fb629_32]],["visible"]=1,["unit4"]=[[npc09v]],["dirIndex"]=0,["unit3"]=[[npc09u]],["unit2"]=[[npc09t]],["unit1"]=[[npc08j]],["canLeave"]=1,["id"]=[[fb629_21]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[毓秀梨芳园]],["permission"]=0,["fullName"]=[[毓秀梨芳园(fb629_22)]],["enterable"]=1,["up"]=[[fb629_14]],["dsc"]=[[天竞门内众多园林各有千秋，毓秀梨芳园独占鳌头。凉亭、假山、池塘应有尽有，疏朗雅适，走廊回环，移步换景，诗意天成。古树花卉也以古、奇、雅、色、香、姿见著，并与建筑、山池相映成趣。]],["down"]=[[fb629_33]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc01]],["canLeave"]=1,["id"]=[[fb629_22]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[清雅居室]],["permission"]=0,["enterable"]=1,["up"]=[[fb629_15]],["dsc"]=[[此居室以原木为梁柱，再以巨石砌墙的双层房屋。外墙上爬满藤蔓，台阶上也长了些青苔，不过屋内却收拾的一尘不染，房内外成鲜明对比。]],["fullName"]=[[清雅居室(fb629_23)]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc09x]],["unit2"]=[[npc09w]],["unit1"]=[[npc08k]],["canLeave"]=1,["id"]=[[fb629_23]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_25]],["connectPoint"]=0,["name"]=[[大门]],["permission"]=0,["enterable"]=1,["dsc"]=[[登上数阶石阶后便是明月楼的大门，大门由两根木制门柱固定，右边柱上写“谁家今夜扁舟子”，左边则是“何处相思明月楼”，初代门主杨儒光便以此句作为楼名，亲自于牌匾上写下“明月楼”三个字。]],["fullName"]=[[大门(fb629_24)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc08l]],["canLeave"]=1,["id"]=[[fb629_24]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_26]],["connectPoint"]=0,["name"]=[[明月楼]],["permission"]=0,["left"]=[[fb629_24]],["enterable"]=1,["up"]=[[fb629_16]],["dsc"]=[[明月楼临江而建，身居闹市，乃是天下闻名的戏楼，不少名家均在此演过戏、奏过曲、舞过剑。即便是如此名胜之地，楼中也并不将来客划分三六九等，上至王公贵胄，下至平头百姓，只要能出得起一碗茶水钱，均能到此楼消遣雅致。]],["down"]=[[fb629_35]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[明月楼(fb629_25)]],["canLeave"]=1,["id"]=[[fb629_25]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_27]],["connectPoint"]=0,["name"]=[[花厅]],["permission"]=0,["left"]=[[fb629_25]],["enterable"]=1,["dsc"]=[[位于明月楼的入口处，摆有数组桌椅，距离戏台有一些距离，并不是观戏的最佳位置，不过一楼也只有此处提供酒菜，因此也颇受欢迎。]],["fullName"]=[[花厅(fb629_26)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc08m]],["canLeave"]=1,["id"]=[[fb629_26]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_28]],["connectPoint"]=0,["name"]=[[池座]],["permission"]=0,["left"]=[[fb629_26]],["fullName"]=[[池座(fb629_27)]],["enterable"]=1,["up"]=[[fb629_17]],["dsc"]=[[此处正对着戏台，摆满了密密麻麻的长板凳，乃是观戏的绝佳位置，每当演出开始便座无虚席。]],["down"]=[[fb629_36]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc09y]],["unit1"]=[[npc08n]],["canLeave"]=1,["id"]=[[fb629_27]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[长廊]],["permission"]=0,["left"]=[[fb629_27]],["fullName"]=[[长廊(fb629_28)]],["enterable"]=1,["dsc"]=[[位于池座和百花园间的单面空廊，能看见百花园中的景色，廊柱间设坐凳供游人休息。]],["down"]=[[fb629_37]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc09z]],["canLeave"]=1,["id"]=[[fb629_28]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_30]],["connectPoint"]=0,["name"]=[[三洗关]],["permission"]=0,["fullName"]=[[三洗关(fb629_29)]],["enterable"]=1,["up"]=[[fb629_18]],["dsc"]=[[天竞门藏匿于明月楼后，凡入天竞门，必经三洗关。关中设乐、卜、医、器等行走江湖必备之物，用来试验弟子身份，只因天竞门弟子遍布江湖，行当驳杂，门内担心有心之人误闯，故设此关卡。]],["down"]=[[fb629_39]],["visible"]=1,["unit4"]=[[25cyshoptianjing]],["dirIndex"]=0,["unit3"]=[[22tianjingcynpc]],["unit2"]=[[shengwang28]],["unit1"]=[[npc05]],["canLeave"]=1,["id"]=[[fb629_29]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_31]],["connectPoint"]=0,["name"]=[[古戏楼]],["permission"]=0,["left"]=[[fb629_29]],["rightDown"]=[[fb629_41]],["enterable"]=1,["up"]=[[fb629_19]],["dsc"]=[[年代久远的戏楼，经历数次翻修后至今仍在使用。其地处天竞门中央，且外延空间较大，因此便成了各脉弟子们交流之地。]],["down"]=[[fb629_40]],["visible"]=1,["fullName"]=[[古戏楼(fb629_30)]],["dirIndex"]=0,["unit2"]=[[npc09aa]],["unit1"]=[[npc08o]],["canLeave"]=1,["id"]=[[fb629_30]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_32]],["connectPoint"]=0,["name"]=[[长廊]],["permission"]=0,["left"]=[[fb629_30]],["enterable"]=1,["dsc"]=[[连接着古戏楼和万愁同销阁的双面空廊，廊顶用两排原木柱支撑，四面无墙无窗、通透明亮。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[长廊(fb629_31)]],["canLeave"]=1,["id"]=[[fb629_31]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_33]],["connectPoint"]=0,["name"]=[[万愁同销阁]],["permission"]=0,["left"]=[[fb629_31]],["enterable"]=1,["up"]=[[fb629_21]],["dsc"]=[[此处为天竞门用于接待来宾或是众门主商议内事的场所，阁内设有正厅，厅内摆有数把官帽椅，墙上则挂有各类书画。]],["fullName"]=[[万愁同销阁(fb629_32)]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc09ca]],["unit1"]=[[npc09ba]],["canLeave"]=1,["id"]=[[fb629_32]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_34]],["connectPoint"]=0,["name"]=[[长廊]],["permission"]=0,["left"]=[[fb629_32]],["enterable"]=1,["up"]=[[fb629_22]],["dsc"]=[[连接万愁同销阁和毓秀梨芳园的双面空廊，廊住间设有栏杆，供人驻足休息。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[长廊(fb629_33)]],["canLeave"]=1,["id"]=[[fb629_33]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[长廊]],["permission"]=0,["left"]=[[fb629_33]],["enterable"]=1,["dsc"]=[[毓秀梨芳园外的木制长廊，与其他长廊相比似乎有些老旧。]],["down"]=[[fb629_44]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[长廊(fb629_34)]],["canLeave"]=1,["id"]=[[fb629_34]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[绕焦坊]],["permission"]=0,["enterable"]=1,["up"]=[[fb629_25]],["dsc"]=[[绕焦坊本名“绕梁”，意在给楼中乐师练琴休息之用。明月楼初建时，曾遭遇有心之人报复焚毁，故屡次修缮，三年才得以完工。杨儒光验收明月楼之日，发觉坊中主横梁上仍有被火烧焦的痕迹，原是工匠一时间难以找到相仿大小的木头，加之此木只是略有火痕，故复用。杨儒光得知后，非但没有斥责工匠，反将坊名更为“绕焦”二字。]],["fullName"]=[[绕焦坊(fb629_35)]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc09da]],["unit1"]=[[npc08p]],["canLeave"]=1,["id"]=[[fb629_35]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[弹压席]],["permission"]=0,["enterable"]=1,["up"]=[[fb629_27]],["dsc"]=[[此席设置在戏台对面楼下靠后方，置有一长方桌，桌上除茶果外还立着一张木牌，上书“弹压席”三个字。由于明月楼来者不拒，鱼龙混杂，为维持楼内秩序特设此席，能坐此位者不是位高权重，便是武功高强，欲闹事者但凡见着此席有人都得忌惮三分。]],["fullName"]=[[弹压席(fb629_36)]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc09fa]],["unit1"]=[[npc09ea]],["canLeave"]=1,["id"]=[[fb629_36]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_38]],["connectPoint"]=0,["name"]=[[百花园]],["permission"]=0,["fullName"]=[[百花园(fb629_37)]],["enterable"]=1,["up"]=[[fb629_28]],["dsc"]=[[种植了各式各样的花草树木，鲜花盛开散发幽香，枝叶形成浓密树荫，一年四季景色各不相同。]],["down"]=[[fb629_45]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc09ga]],["canLeave"]=1,["id"]=[[fb629_37]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_39]],["connectPoint"]=0,["name"]=[[暗门]],["permission"]=0,["left"]=[[fb629_37]],["enterable"]=1,["dsc"]=[[隐藏于百花园的假山之中，与周边环境融为一体，只有天竞门门徒才知道如何开启，穿过此门后便能到达天竞门。]],["fullName"]=[[暗门(fb629_38)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc09ha]],["canLeave"]=1,["id"]=[[fb629_38]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[天竞门]],["permission"]=0,["left"]=[[fb629_38]],["fullName"]=[[天竞门(fb629_39)]],["enterable"]=1,["up"]=[[fb629_29]],["dsc"]=[[高数十尺的石制大门，乃天竞门真正的入口，上有牌匾写着“天竞门”三个大字，弟子们每每经过此门便回想先祖“与天竞，与地争，不求不怨，唯凭自身立世存活”之心。]],["down"]=[[fb629_46]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc08q]],["canLeave"]=1,["id"]=[[fb629_39]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[千鲤池]],["permission"]=0,["fullName"]=[[千鲤池(fb629_40)]],["enterable"]=1,["up"]=[[fb629_30]],["dsc"]=[[池内养有众多锦鲤，在人细心照料下最大已达数尺长，池面上设有踏脚石供人行走。]],["down"]=[[fb629_47]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc09ia]],["canLeave"]=1,["id"]=[[fb629_40]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_42]],["connectPoint"]=0,["name"]=[[回廊]],["permission"]=0,["enterable"]=1,["dsc"]=[[连接着古戏楼和梨园的双面空廊，廊顶用两排原木柱支撑，四面无墙无窗，通透明亮。]],["fullName"]=[[回廊(fb629_41)]],["visible"]=1,["dirIndex"]=0,["leftUp"]=[[fb629_30]],["canLeave"]=1,["id"]=[[fb629_41]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb629_43]],["connectPoint"]=0,["name"]=[[梨园]],["permission"]=0,["left"]=[[fb629_41]],["enterable"]=1,["dsc"]=[[一条石砌的石板路贯穿全园，路的两旁种满了梨树，花开之时如同满天飞雪。]],["fullName"]=[[梨园(fb629_42)]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc09o]],["unit1"]=[[npc09n]],["canLeave"]=1,["id"]=[[fb629_42]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[列芳堂]],["permission"]=0,["left"]=[[fb629_42]],["enterable"]=1,["dsc"]=[[列芳堂位置偏远，乃是祭奠历代天竞门先祖之地，牌匾上写“列芳堂”几个大字，内部陈设简洁，仅在堂前设一前一后两张供桌，一张桌上摆着历代天竞门先祖牌位，另一张则放着香炉、烛台等祭祀用具和一些酒肉祭品。]],["fullName"]=[[列芳堂(fb629_43)]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc09ka]],["unit1"]=[[npc09ja]],["canLeave"]=1,["id"]=[[fb629_43]],["mapHide"]=0},