[[fb629_08]],["name"]=[[弟子]],["behaviourStageList"]={{["skillPrepare"]={{["lv"]=250,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=250,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=250,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=250,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[卜浩]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=33,["jiali"]=100,["neili"]=100,["sex"]=[[男]],["lv"]=250,["dex"]=20,["unitType"]=[[role]],["looks"]=17,["stageId"]=[[npc08a]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[经我掐腿一算，看来是要下雨了。;嗯，嗯，原来如此，你问我卜到了啥？天机不可泄露啊。;我昨日夜观天象，顺带偷看一眼厨房，得知今天应该有鸡肉吃了。]],["dsc"]=[[卜浩在拜入天竞门前居无定所，打着卜卦算命的幌子四处坑蒙拐骗，凭借着一口伶牙俐齿屡屡得手。但在一次行骗过程中被人揭穿，腿也因此被打折了一条，从此决定痛改前非，认真专研卜卦。]],["con"]=20},{["skillPrepare"]={{["lv"]=250,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=250,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=250,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=250,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[韶风]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=15,["jiali"]=100,["neili"]=100,["sex"]=[[男]],["lv"]=250,["dex"]=20,["unitType"]=[[role]],["looks"]=17,["stageId"]=[[npc08b]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[这一曲是为远方家人而作，以表我对他们的思念之情。;寄回家的信如石沉大海，几年来一封回信都没有。;有朝一日希望父亲能听听我的演奏。]],["dsc"]=[[韶风年幼时无师自通便能写琴谱，其父见状却带着他四处给人写曲赚钱，韶风的天赋被白白浪费。一日一位乐师到戏楼奏曲演出，韶风下定决心请求乐师带他离开。后来在乐师的引荐下拜入了天竞门。]],["con"]=20},{["skillPrepare"]={{["lv"]=250,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=250,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=250,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=250,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[解梭]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=23,["jiali"]=100,["neili"]=100,["sex"]=[[女]],["lv"]=250,["dex"]=20,["unitType"]=[[role]],["looks"]=19,["stageId"]=[[npc08c]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[一别京城数年，不知公子如今是否安好。;时常梦见京城那时，唯独没能梦见公子，只能流泪到天明。;我想回京城看一看，但又怕被人抓回去。]],["dsc"]=[[解梭本是京城小负盛名的歌伎，深受富家子弟们的喜爱，可后来家道衰落，养父便想将她送给富商做小妾，她只好连夜出逃，机缘巧合下来到明月楼卖艺，后被引荐去了天竞门。]],["con"]=20},{["skillPrepare"]={{["lv"]=250,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=250,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=250,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=250,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[高成]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=46,["jiali"]=100,["neili"]=100,["sex"]=[[男]],["lv"]=250,["dex"]=20,["unitType"]=[[role]],["looks"]=17,["stageId"]=[[npc08d]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[要我说戏乐曲也就听个乐呵，明月楼的美食佳肴才是一绝。;你看看台上戏子们打的有模有样的，其实都是些花拳绣腿，我上我也能露个两手。;台下看客的反映比台上有趣多了，翻个跟头都能欢呼老半天。]],["dsc"]=[[高成是苏州当地的员外。原名为高楠，早年经商失败，算命先生认为他名中带“难”字不讨吉利，便改名为高成，从此生意一帆风顺。]],["con"]=20},{["skillPrepare"]={{["lv"]=250,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=250,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=250,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=250,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[店小二]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=26,["jiali"]=100,["neili"]=100,["sex"]=[[男]],["lv"]=250,["dex"]=20,["unitType"]=[[role]],["looks"]=19,["stageId"]=[[npc08e]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[客官您随便坐，有需要尽管使唤小人。;松鼠桂鱼乃是苏州特色菜，吃起来外脆里嫩、酸甜适口，客官不来一份么？;本店的秘制东坡肉，色泽红亮，软而不烂，味醇汁浓，肥而不腻，客官不尝尝么？]],["dsc"]=[[他是明月楼的伙计，因其精明能干，能说会道，便被安排在二楼，负责接待达官贵人。]],["con"]=20},{["skillPrepare"]={{["lv"]=250,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=250,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=250,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=250,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[沈程]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=19,["jiali"]=100,["neili"]=100,["sex"]=[[男]],["lv"]=250,["dex"]=20,["unitType"]=[[role]],["looks"]=19,["stageId"]=[[npc08f]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[嗯，有何贵干么？;找我么？;没事的话就让我一个人待着吧。]],["dsc"]=[[沈程是天竞门的弟子，平日里独来独往，沉默寡言，不苟言笑，最大的兴趣便是一个人在安静的角落里看书。]],["con"]=20},{["skillPrepare"]={{["lv"]=250,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=250,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=250,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=250,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[吕朔]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=30,["jiali"]=100,["neili"]=100,["sex"]=[[男]],["lv"]=250,["dex"]=20,["unitType"]=[[role]],["looks"]=17,["stageId"]=[[npc08g]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[工架我还勉强能应付，开口唱戏简直要了老命。;唱戏虽然辛苦，但也比街边卖艺强。;就我这破锣嗓子，也就只能演些词少的角了。]],["dsc"]=[[吕朔出身家境贫寒，自学了些拳脚功夫，却在去参加武举的路上散尽盘缠，进退不能，只能以卖艺为生，后在人引荐下拜入天竞门门下。]],["con"]=20},{["skillPrepare"]={{["lv"]=400,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=400,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=300,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=400,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[薛横]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=40,["jiali"]=100,["neili"]=100,["sex"]=[[男]],["lv"]=400,["dex"]=20,["unitType"]=[[role]],["looks"]=18,["stageId"]=[[npc08h]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[我曾经也怀有满腔热血，但如今只求能有一口饭吃。;人们喜欢歌颂伟大的英雄，却忘了英雄背后的小人物。;我演不了英雄，也不配演英雄。]],["dsc"]=[[薛横是天竞门的弟子，早年应征入伍，在一次作战中战况失利，自己连人带马摔下悬崖。因害怕被当成逃兵，于是隐姓埋名，如孤魂野鬼般四处游荡。后有幸来到明月楼，凭着一身功夫找了个武角混口饭吃。]],["con"]=20},{["skillPrepare"]={{["lv"]=400,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=400,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=300,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=400,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[萧茗]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=22,["jiali"]=100,["neili"]=100,["sex"]=[[女]],["lv"]=400,["dex"]=20,["unitType"]=[[role]],["looks"]=20,["stageId"]=[[npc08i]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[呼呼，我没事，稍微休息一下就可以了。;我宁愿猝死在戏台上，也不愿躺在床上度过一生。;你也是来休息的么？这儿的景色总能让人的内心恢复平静。]],["dsc"]=[[萧茗从小体弱多病，稍微活动身体便会喘得上气不接下气。在拜入天竞门后症状有所好转，不过每次唱完戏后还是得休息好一会儿才能恢复过来。]],["con"]=20},{["skillPrepare"]={{["lv"]=400,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=400,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=400,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=400,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[项安]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=50,["jiali"]=100,["neili"]=100,["sex"]=[[男]],["lv"]=400,["dex"]=20,["unitType"]=[[role]],["looks"]=15,["stageId"]=[[npc08j]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[里侧书架上多是些损坏待修复的书籍，如要找书还请在别的书架上找吧。;外侧书架上的书可随意翻阅。;墨白轩内光线较差，找书时还请多集中注意力。]],["dsc"]=[[项安虽尚处中年，但已是须发灰白，行动缓慢，一副老态龙钟的样子。他担任墨白轩管理已有几十载，平日里极少出门。]],["con"]=20},{["skillPrepare"]={{["lv"]=400,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=400,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=500,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=400,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[元鳞]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=27,["jiali"]=100,["neili"]=100,["sex"]=[[男]],["lv"]=400,["dex"]=20,["unitType"]=[[role]],["looks"]=11,["stageId"]=[[npc08k]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[我常常在想，如果台下的看客知道妆容下是这么一张脸时，是否还能像这样为我喝彩。;我已不再害怕直视我的面容，但我还是害怕别人看到我面容时那惊恐的表情。;或许哪天我能够不用戴面具与你交谈，但现在还不行。]],["dsc"]=[[元鳞是天竞门弟子，是明月楼的台柱之一。但几年前的一场大火几近夺去了他的性命，从此他便戴着脸谱面具遮挡脸上伤痕。但大火未能彻底击垮元鳞，如今在明月楼的戏台上还能看见元鳞那活跃的身影。]],["con"]=20},{["skillPrepare"]={{["lv"]=250,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=250,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=250,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=250,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[乞丐]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=41,["jiali"]=100,["neili"]=100,["sex"]=[[男]],["lv"]=250,["dex"]=20,["unitType"]=[[role]],["looks"]=17,["stageId"]=[[npc08l]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[大人赏几个铜钱让我买口酒呗。;大人行行好，我几天没吃过饭了。;朱门酒肉臭啊，路有冻死骨啊。]],["dsc"]=[[一个在门口徘徊的乞丐，圆润的脸上沾了些污泥，衣服虽然破旧但却不脏，看上去十分可疑。]],["con"]=20},{["skillPrepare"]={{["lv"]=250,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=250,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=250,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=250,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[伙计]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=32,["jiali"]=100,["neili"]=100,["sex"]=[[男]],["lv"]=250,["dex"]=20,["unitType"]=[[role]],["looks"]=17,["stageId"]=[[npc08m]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[客官今日是想坐花厅还是池座？;客官有何需要么？;客官若要看戏往里找位置坐便是了。]],["dsc"]=[[在花厅和池座之间穿梭着，负责给客人端茶倒水，点单上菜，忙得不可开交。]],["con"]=20},{["skillPrepare"]={{["lv"]=250,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=250,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=250,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=250,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[张七]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=36,["jiali"]=100,["neili"]=100,["sex"]=[[男]],["lv"]=250,["dex"]=20,["unitType"]=[[role]],["looks"]=15,["stageId"]=[[npc08n]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[好，唱的好！;诶，你别挡着我看戏。;叫上一碗茶水便能听名家唱戏，真值。]],["dsc"]=[[他是苏州人，穿着一身简易的衣物，正坐在板凳上目不转睛的盯着戏台看。]],["con"]=20},{["skillPrepare"]={{["lv"]=250,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=250,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=250,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=250,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[任思贤]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=27,["jiali"]=100,["neili"]=100,["sex"]=[[女]],["lv"]=250,["dex"]=20,["unitType"]=[[role]],["looks"]=18,["stageId"]=[[npc08o]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[这几个大老爷们还不如我呢，练没几下就直喘粗气。;我也曾想担当花旦，但一开口便破了功。;有的戏曲一开口便是情呀爱呀，搞得要死要活的，哪来那么多矫情。]],["dsc"]=[[任思贤为家中独女，从小其父便将其作为儿子养育，为人豪迈、爽朗。后拜入天竞门，学得一身好武艺，常在戏中担当刀马旦，颇有巾帼不让须眉的气魄。]],["con"]=20},{["skillPrepare"]={{["lv"]=250,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=250,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=250,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=250,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[赵观月]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=15,["jiali"]=100,["neili"]=100,["sex"]=[[女]],["lv"]=250,["dex"]=20,["unitType"]=[[role]],["looks"]=18,["stageId"]=[[npc08p]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[呼……嗯……啊，我没有睡着哦。;现在还在休息，如要听我演奏还请等到演出开始吧。;我跟你说个秘密，其实我每次上台前都紧张的手抖。]],["dsc"]=[[赵观月是苏州当地的乐师，琴法技艺上虽欠些火候，但未来可期。]],["con"]=20},{["skillPrepare"]={{["lv"]=400,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=400,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=400,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=400,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[秦飞]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=39,["jiali"]=100,["neili"]=100,["sex"]=[[男]],["lv"]=400,["dex"]=20,["unitType"]=[[role]],["looks"]=18,["stageId"]=[[npc08q]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[前走便是三洗关了。;门徒未经许可不得闯入三洗关。;如要前去照影居还请多加防范，至少我是不愿与他们为伍的。]],["dsc"]=[[秦飞是天竞门的弟子，乃是山中强盗出身，金盆洗手后投奔了一间镖局。最初只被天竞门收为门徒，后见他早已痛改前非便让他拜入内门。]],["con"]=20},{["skillPrepare"]={{["lv"]=400,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=400,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=500,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=400,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[时百万]],["baseId"]=[[fb629_08]],["skills"]={},["items"]={},["age"]=47,["jiali"]=100,["neili"]=100,["sex"]=[[男]],["lv"]=400,["dex"]=20,["unitType"]=[[role]],["looks"]=15,["stageId"]=[[npc08r]],["isVisible"]=1,["qi"]=100,["str"]=20,["words"]=[[无数次的发誓要金盆洗手，但就是管不住我这手啊。;偷盗时的那种紧张感，以及得手后的成就感，你是没办法理解的。;上次又未能通过三洗关，但要我说干我这行的也算是靠手艺吃饭，并不比关内那些人低贱。]],["dsc"]=[[盗墓、抢劫、偷窃都干过，一次入室偷窃时被琴师所奏音乐声吸引，整个人如大梦初醒，一连跪了数日，请求琴师收他为徒，后在琴师指引下被天竞门收为门徒，但贼性复发，迟迟未能拜入内门。]],["con"]=20},{["skillPrepare"]={{["lv"]=400,["preSkillType"]=0,["skillId"]=[[chunyanggong]]},{["lv"]=400,["preSkillType"]=2,["skillId"]=[[jibenneigong]]},{["lv"]=600,["preSkillType"]=3,["skillId"]=[[jibenqinggong]]},{["lv"]=400,["preSkillType"]=4,["skillId"]=[[jibenzhaojia]]}},["operations"]={{["isEnable"]=1,["condOperator"]=[[and]],["results"]={{["arg1"]=[[交谈]]}},["operationButton"]=[[交谈]],["faildResults"]={},["isVisible"]=1,["conditions"]={},["id"]=[[talk]]}},["name"]=[[杨永]],["baseId"]=[[fb629_08]],["skills"]={},["items"